import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('fresh system is idle', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle' });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nope'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('start sends Assign; refused twice', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [
    ['run', 'worker0', 'Assign', {}],
    ['run', 'worker1', 'Assign', {}],
  ]);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned' });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
});

test('happy path completes', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  assert.equal((await h.workDone('worker0')).ok, true);
  assert.equal((await h.workDone('worker0')).ok, false);
  const [m] = await h.inFlight();
  assert.deepEqual([m.from, m.to, m.action, m.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned' });
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed' });
});

test('failure waits for both reports', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.equal((await h.run()).status, 'running');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed' });
});

test('cancel aborts only assigned tasks', async () => {
  const h = await createHost();
  assert.equal((await h.cancel()).ok, false);
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.to, m.action]), [['worker1', 'Abort']]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled' });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('cancel then both complete is completed', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.cancel();
  await h.workDone('worker0');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed' });
});

test('refusals with bad ids', async () => {
  const h = await createHost();
  assert.equal((await h.workDone('x')).ok, false);
  assert.equal((await h.workFailed('worker0')).ok, false);
});

// Exhaustive: every interleaving of commands and deliveries (bounded), checking the brief's rules.
test('exhaustive interleavings respect the rules', async () => {
  type Step = { kind: string; arg?: string };
  const reports: Record<string, number> = {};
  let explored = 0;
  const replay = async (path: Step[]) => {
    const h = await createHost();
    for (const s of path) {
      if (s.kind === 'start') await h.start();
      else if (s.kind === 'cancel') await h.cancel();
      else if (s.kind === 'done') await h.workDone(s.arg!);
      else if (s.kind === 'fail') await h.workFailed(s.arg!);
      else if (s.kind === 'deliver') {
        const m = (await h.inFlight()).find((x) => `${x.to}:${x.action}:${JSON.stringify(x.data)}` === s.arg);
        if (m) await h.deliver(m.id);
      }
    }
    return h;
  };
  const check = async (h: Awaited<ReturnType<typeof createHost>>) => {
    const r = await h.run();
    const reported = [r.task0, r.task1].every((t) => t !== 'assigned' && t !== 'idle');
    if (r.status === 'completed') assert.ok(r.task0 === 'completed' && r.task1 === 'completed');
    if (r.status === 'failed') assert.ok(reported && (r.task0 === 'failed' || r.task1 === 'failed'));
    if (r.status === 'cancelled') assert.ok(reported && r.task0 !== 'failed' && r.task1 !== 'failed');
    if (reported) assert.ok(['completed', 'failed', 'cancelled'].includes(r.status));
    for (const [i, w] of ['worker0', 'worker1'].entries()) {
      const t = i === 0 ? r.task0 : r.task1;
      if ((await h.worker(w))!.status === 'busy') assert.equal(t, 'assigned');
    }
    const msgs = await h.inFlight();
    for (const m of msgs) {
      if (m.action === 'Report') {
        const k = JSON.stringify(m.data);
        reports[k] = (reports[k] ?? 0) + 1;
      }
    }
  };
  const dfs = async (path: Step[], depth: number) => {
    explored++;
    const h = await replay(path);
    await check(h);
    if (depth === 0) return;
    const steps: Step[] = [
      { kind: 'start' }, { kind: 'cancel' },
      { kind: 'done', arg: 'worker0' }, { kind: 'done', arg: 'worker1' },
      { kind: 'fail', arg: 'worker0' }, { kind: 'fail', arg: 'worker1' },
    ];
    const seen = new Set<string>();
    for (const m of await h.inFlight()) {
      const k = `${m.to}:${m.action}:${JSON.stringify(m.data)}`;
      if (!seen.has(k)) { seen.add(k); steps.push({ kind: 'deliver', arg: k }); }
    }
    for (const s of steps) {
      // prune refused commands: they change nothing
      if (s.kind === 'start' && path.some((p) => p.kind === 'start')) continue;
      if (s.kind !== 'deliver' && s.kind !== 'start' && !path.some((p) => p.kind === 'start')) continue;
      if (s.kind === 'cancel' && path.some((p) => p.kind === 'cancel')) continue;
      await dfs([...path, s], depth - 1);
    }
  };
  await dfs([], 8);
  assert.ok(explored > 1000);
});

