    for (const s of path) {
      if (s.kind === 'start') await h.start();
      else if (s.kind === 'cancel') await h.cancel();
      else if (s.kind === 'done') await h.workDone(s.arg!);
      else if (s.kind === 'fail') await h.workFailed(s.arg!);
      else if (s.kind === 'deliver') {
        const m = (await h.inFlight()).find((x) => `${x.to}:${x.action}:${JSON.stringify(x.data)}` === s.arg);
        if (m) await h.deliver(m.id);
      }
    }
    return h;
  };
  const check = async (h: Awaited<ReturnType<typeof createHost>>) => {
    const r = await h.run();
    const reported = [r.task0, r.task1].every((t) => t !== 'assigned' && t !== 'idle');
    if (r.status === 'completed') assert.ok(r.task0 === 'completed' && r.task1 === 'completed');
    if (r.status === 'failed') assert.ok(reported && (r.task0 === 'failed' || r.task1 === 'failed'));
    if (r.status === 'cancelled') assert.ok(reported && r.task0 !== 'failed' && r.task1 !== 'failed');
    if (reported) assert.ok(['completed', 'failed', 'cancelled'].includes(r.status));
    for (const [i, w] of ['worker0', 'worker1'].entries()) {
      const t = i === 0 ? r.task0 : r.task1;
      if ((await h.worker(w))!.status === 'busy') assert.equal(t, 'assigned');
    }
    const msgs = await h.inFlight();
    for (const m of msgs) {
      if (m.action === 'Report') {
        const k = JSON.stringify(m.data);
        reports[k] = (reports[k] ?? 0) + 1;
      }
    }
  };
  const dfs = async (path: Step[], depth: number) => {
    explored++;
    const h = await replay(path);
    await check(h);
    if (depth === 0) return;
    const steps: Step[] = [
      { kind: 'start' }, { kind: 'cancel' },
      { kind: 'done', arg: 'worker0' }, { kind: 'done', arg: 'worker1' },
      { kind: 'fail', arg: 'worker0' }, { kind: 'fail', arg: 'worker1' },
    ];
    const seen = new Set<string>();
    for (const m of await h.inFlight()) {
      const k = `${m.to}:${m.action}:${JSON.stringify(m.data)}`;
      if (!seen.has(k)) { seen.add(k); steps.push({ kind: 'deliver', arg: k }); }
    }
    for (const s of steps) {
      // prune refused commands: they change nothing
      if (s.kind === 'start' && path.some((p) => p.kind === 'start')) continue;
      if (s.kind !== 'deliver' && s.kind !== 'start' && !path.some((p) => p.kind === 'start')) continue;
      if (s.kind === 'cancel' && path.some((p) => p.kind === 'cancel')) continue;
      await dfs([...path, s], depth - 1);
    }
  };
  await dfs([], 8);
  assert.ok(explored > 1000);
});

