test('timeout records a final failure and aborts the worker', async () => {
  const h = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start();
  assert.equal((await h.taskTimeout(2)).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.equal((await h.taskTimeout(0)).ok, false);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', retried0: false, retried1: false });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]), [['run', 'worker0', 'Abort', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  // the cancelled report from the abort was ignored
  assert.equal((await h.run()).task0, 'failed');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', retried0: false, retried1: false });
});

test('late report after timeout is ignored; timeout allowed while cancelling', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0');
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  await h.deliverAll();
  assert.equal((await h.run()).task0, 'failed');
  await h.cancel();
  assert.deepEqual(await h.taskTimeout(1), { ok: true });
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'failed', retried0: false, retried1: false });
  assert.equal((await h.taskTimeout(1)).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'failed', retried0: false, retried1: false });
});

test('timeout of a pending first failure prevents the retry', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
