'use strict';

// SAM v2 strict-profile spec of src/host.impl.ts: the run, its two workers,
// and the network between them. A message in transit is a string key
// ('Assign:0', 'Abort:1', 'Report:0:completed'); `net` is the multiset of
// keys in transit, kept sorted so equal multisets are equal states.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = { run: 'idle', task0: 'idle', task1: 'idle', w0: 'idle', w1: 'idle', retried0: false, retried1: false, net: [] };

const MESSAGES = [
  'Assign:0', 'Assign:1', 'Abort:0', 'Abort:1',
  'Report:0:completed', 'Report:0:failed', 'Report:0:cancelled',
  'Report:1:completed', 'Report:1:failed', 'Report:1:cancelled',
];

const add = (net, ...ms) => [...net, ...ms].sort();
const remove = (net, m) => {
  const i = net.indexOf(m);
  return [...net.slice(0, i), ...net.slice(i + 1)];
};
const terminal = (s) => s === 'completed' || s === 'failed' || s === 'cancelled';
const wKey = (i) => (i === 0 ? 'w0' : 'w1');
const tKey = (i) => (i === 0 ? 'task0' : 'task1');
const rKey = (i) => (i === 0 ? 'retried0' : 'retried1');
const workerDomain = [{ worker: 'worker0' }, { worker: 'worker1' }, { worker: 'other' }];
const workerIndex = (id) => (id === 'worker0' ? 0 : id === 'worker1' ? 1 : -1);

const finish = (outcome) => (model) => (proposal, { reject, next, unchanged }) => {
  const i = workerIndex(proposal.worker);
  if (i < 0) return reject('unknown-worker');
  if (model[wKey(i)] !== 'busy') return reject('worker-not-busy');
  next[wKey(i)] = 'idle';
  next.net = add(model.net, `Report:${i}:${outcome}`);
  unchanged('run', 'task0', 'task1', wKey(1 - i), 'retried0', 'retried1');
};

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      run: { type: 'string' },
      task0: { type: 'string' },
      task1: { type: 'string' },
      w0: { type: 'string' },
      w1: { type: 'string' },
      retried0: { type: 'boolean' },
      retried1: { type: 'boolean' },
      net: { type: 'array' },
    },
    actions: {
      START: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      CANCEL: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      WORK_DONE: { action: (data = {}) => ({ ...data }), schema: { worker: 'string' }, domain: workerDomain },
      WORK_FAILED: { action: (data = {}) => ({ ...data }), schema: { worker: 'string' }, domain: workerDomain },
      DELIVER: {
        action: (data = {}) => ({ ...data }),
        schema: { msg: 'string' },
        domain: MESSAGES.map((msg) => ({ msg })),
      },
    },
    acceptors: {
      START: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.run !== 'idle') return reject('already-started');
        next.run = 'running';
        next.task0 = 'assigned';
        next.task1 = 'assigned';
        next.net = add(model.net, 'Assign:0', 'Assign:1');
        unchanged('w0', 'w1', 'retried0', 'retried1');
      },
      CANCEL: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.run !== 'running') return reject('not-running');
        const aborts = [0, 1].filter((i) => model[tKey(i)] === 'assigned').map((i) => `Abort:${i}`);
        next.run = 'cancelling';
        next.net = add(model.net, ...aborts);
        unchanged('task0', 'task1', 'w0', 'w1', 'retried0', 'retried1');
      },
      WORK_DONE: finish('completed'),
      WORK_FAILED: finish('failed'),
      DELIVER: (model) => (proposal, { reject, next, unchanged }) => {
        const msg = proposal.msg;
        if (!model.net.includes(msg)) return reject('not-in-flight');
        const [kind, idx, outcome] = msg.split(':');
        const i = Number(idx);
        if (kind === 'Assign') {
          next.net = remove(model.net, msg);
          next[wKey(i)] = model[wKey(i)] === 'idle' ? 'busy' : model[wKey(i)];
          unchanged('run', 'task0', 'task1', wKey(1 - i), 'retried0', 'retried1');
          return;
        }
        if (kind === 'Abort') {
          if (model[wKey(i)] !== 'busy') {
            next.net = remove(model.net, msg);
            unchanged('run', 'task0', 'task1', 'w0', 'w1', 'retried0', 'retried1');
            return;
          }
          next[wKey(i)] = 'idle';
          next.net = add(remove(model.net, msg), `Report:${i}:cancelled`);
          unchanged('run', 'task0', 'task1', wKey(1 - i), 'retried0', 'retried1');
          return;
        }
        // Report: consumed; recorded only by a live run, once per task.
        if (model.run === 'idle' || terminal(model.run) || model[tKey(i)] !== 'assigned') {
          next.net = remove(model.net, msg);
          unchanged('run', 'task0', 'task1', 'w0', 'w1', 'retried0', 'retried1');
          return;
        }
        // A first failure while running is retried once: re-Assign, task stays assigned.
        if (outcome === 'failed' && model.run === 'running' && !model[rKey(i)]) {
          next.net = add(remove(model.net, msg), `Assign:${i}`);
          next[rKey(i)] = true;
          unchanged('run', 'task0', 'task1', rKey(1 - i), 'w0', 'w1');
          return;
        }
        const t = [model.task0, model.task1];
        t[i] = outcome;
        const reported = t[0] !== 'assigned' && t[1] !== 'assigned';
        let run = model.run;
        if (t[0] === 'completed' && t[1] === 'completed') run = 'completed';
        else if (reported && (t[0] === 'failed' || t[1] === 'failed')) run = 'failed';
        else if (reported) run = 'cancelled';
        next.net = remove(model.net, msg);
        next[tKey(i)] = outcome;
        next.run = run;
        unchanged(tKey(1 - i), 'retried0', 'retried1', 'w0', 'w1');
      },
    },
    reactors: [],
  },
});

