// The brief's rules, stated as intent over the spec's state.
const TERMINAL = ['completed', 'failed', 'cancelled'];
const reported = (t) => TERMINAL.includes(t);
const tasks = (s) => [s.task0, s.task1];
const count = (net, m) => net.filter((x) => x === m).length;

export const stateInvariants = [
  { name: 'completed-only-if-both-completed', pred: (s) => s.run !== 'completed' || tasks(s).every((t) => t === 'completed') },
  { name: 'ends-only-when-both-reported', pred: (s) => !TERMINAL.includes(s.run) || tasks(s).every(reported) },
  { name: 'failed-only-if-a-task-failed', pred: (s) => s.run !== 'failed' || tasks(s).includes('failed') },
  { name: 'cancelled-means-none-failed-not-both-completed',
    pred: (s) => s.run !== 'cancelled' || (!tasks(s).includes('failed') && !tasks(s).every((t) => t === 'completed')) },
  { name: 'both-reported-means-ended', pred: (s) => !tasks(s).every(reported) || TERMINAL.includes(s.run) },
  { name: 'busy-worker-task-still-assigned',
    pred: (s) => (s.w0 !== 'busy' || s.task0 === 'assigned') && (s.w1 !== 'busy' || s.task1 === 'assigned') },
  { name: 'task-cancelled-only-after-cancel', pred: (s) => !tasks(s).includes('cancelled') || s.run !== 'running' },
  { name: 'idle-run-has-idle-tasks', pred: (s) => s.run !== 'idle' || (s.task0 === 'idle' && s.task1 === 'idle' && s.net.length === 0) },
  { name: 'idle-run-not-retried', pred: (s) => s.run !== 'idle' || (!s.retried0 && !s.retried1) },
  { name: 'at-most-one-assign-per-task-in-flight', pred: (s) => [0, 1].every((i) => count(s.net, `Assign:${i}`) <= 1) },
  { name: 'at-most-one-report-per-task-in-flight',
    pred: (s) => [0, 1].every((i) => ['completed', 'failed', 'cancelled'].reduce((n, o) => n + count(s.net, `Report:${i}:${o}`), 0) <= 1) },
];

export const transitionInvariants = [
  { name: 'ended-run-never-changes',
    pred: (pre, a, d, post) => !TERMINAL.includes(pre.run) || (post.run === pre.run && post.task0 === pre.task0 && post.task1 === pre.task1) },
  { name: 'reported-task-never-changes',
    pred: (pre, a, d, post) => [0, 1].every((i) => !reported(tasks(pre)[i]) || tasks(post)[i] === tasks(pre)[i]) },
  { name: 'cancel-aborts-only-assigned-work',
    pred: (pre, a, d, post) => a !== 'CANCEL' || [0, 1].every((i) =>
      count(post.net, `Abort:${i}`) - count(pre.net, `Abort:${i}`) === (pre.run === 'running' && tasks(pre)[i] === 'assigned' ? 1 : 0)) },
  { name: 'retried-flag-never-clears',
    pred: (pre, a, d, post) => (!pre.retried0 || post.retried0) && (!pre.retried1 || post.retried1) },
  { name: 'first-failure-while-running-is-retried',
    pred: (pre, a, d, post) => {
      if (a !== 'DELIVER' || !/^Report:\d:failed$/.test(d.msg) || !pre.net.includes(d.msg)) return true;
      const i = Number(d.msg[7]);
      const t = (s) => tasks(s)[i];
      const r = (s) => (i === 0 ? s.retried0 : s.retried1);
      if (t(pre) !== 'assigned' || TERMINAL.includes(pre.run)) return true;
      if (pre.run === 'running' && !r(pre)) {
        return t(post) === 'assigned' && r(post) && post.run === pre.run
          && count(post.net, `Assign:${i}`) === count(pre.net, `Assign:${i}`) + 1;
      }
      // second failure, or failure while cancelling: recorded, no retry
      return t(post) === 'failed' && r(post) === r(pre) && count(post.net, `Assign:${i}`) === count(pre.net, `Assign:${i}`);
    } },
  { name: 'only-start-or-retry-sends-assign',
    pred: (pre, a, d, post) => a === 'START' || [0, 1].every((i) =>
      count(post.net, `Assign:${i}`) <= count(pre.net, `Assign:${i}`)
      || (a === 'DELIVER' && d.msg === `Report:${i}:failed` && !(i === 0 ? pre.retried0 : pre.retried1))) },
  { name: 'only-cancel-sends-abort',
    pred: (pre, a, d, post) => a === 'CANCEL' || [0, 1].every((i) => count(post.net, `Abort:${i}`) <= count(pre.net, `Abort:${i}`)) },
];

export default { stateInvariants, transitionInvariants };

