// Negative control, not the real invariants (those are invariants.mjs): every
// rule here is EXPECTED to be violated, proving the checker reaches each run
// outcome and can report a failure. Run with --invariants spec/_control.mjs.
export const stateInvariants = [
  { name: 'never-completed', pred: (s) => s.run !== 'completed' },
  { name: 'never-failed', pred: (s) => s.run !== 'failed' },
  { name: 'never-cancelled', pred: (s) => s.run !== 'cancelled' },
  { name: 'never-retried', pred: (s) => !s.retried0 && !s.retried1 },
  { name: 'never-failed-after-retry', pred: (s) => !(s.task0 === 'failed' && s.retried0) },
  { name: 'never-failed-without-retry', pred: (s) => !(s.task0 === 'failed' && !s.retried0) },
  { name: 'never-cancelled-with-a-completed-task', pred: (s) => !(s.run === 'cancelled' && (s.task0 === 'completed' || s.task1 === 'completed')) },
];
export const transitionInvariants = [
  { name: 'cancelling-never-completes', pred: (pre, a, d, post) => !(pre.run === 'cancelling' && post.run === 'completed') },
];
export default { stateInvariants, transitionInvariants };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('fresh system is idle', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle', retried0: false, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nope'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('start sends Assign; refused twice', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [
    ['run', 'worker0', 'Assign', {}],
    ['run', 'worker1', 'Assign', {}],
  ]);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: false, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
});

test('happy path completes', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  assert.equal((await h.workDone('worker0')).ok, true);
  assert.equal((await h.workDone('worker0')).ok, false);
  const [m] = await h.inFlight();
  assert.deepEqual([m.from, m.to, m.action, m.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned', retried0: false, retried1: false });
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false });
});

test('first failure is retried, second is recorded; failure waits for both reports', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: true, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', retried0: true, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', retried0: true, retried1: false });
});

test('retry sends Assign to the failed worker only', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  const [r] = await h.inFlight();
  await h.deliver(r.id);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]), [['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  await h.workDone('worker1');
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: true });
});

test('failure while cancelling is recorded, not retried', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'cancelled', retried0: false, retried1: false });
  assert.deepEqual(await h.inFlight(), []);
});

test('cancel aborts only assigned tasks', async () => {
  const h = await createHost();
  assert.equal((await h.cancel()).ok, false);
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.to, m.action]), [['worker1', 'Abort']]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled', retried0: false, retried1: false });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('cancel then both complete is completed', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.cancel();
  await h.workDone('worker0');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false });
});

test('refusals with bad ids', async () => {
  const h = await createHost();
  assert.equal((await h.workDone('x')).ok, false);
  assert.equal((await h.workFailed('worker0')).ok, false);
});

test('timeout records a final failure and aborts the worker', async () => {
  const h = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start();
  assert.equal((await h.taskTimeout(2)).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.equal((await h.taskTimeout(0)).ok, false);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', retried0: false, retried1: false });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]), [['run', 'worker0', 'Abort', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  // the cancelled report from the abort was ignored
  assert.equal((await h.run()).task0, 'failed');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', retried0: false, retried1: false });
});

test('late report after timeout is ignored; timeout allowed while cancelling', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0');
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  await h.deliverAll();
  assert.equal((await h.run()).task0, 'failed');
  await h.cancel();
