1	// The brief's rules, stated as intent over the spec's state.
2	const TERMINAL = ['completed', 'failed', 'cancelled'];
3	const reported = (t) => TERMINAL.includes(t);
4	const tasks = (s) => [s.task0, s.task1];
5	const count = (net, m) => net.filter((x) => x === m).length;
6	
7	export const stateInvariants = [
8	  { name: 'completed-only-if-both-completed', pred: (s) => s.run !== 'completed' || tasks(s).every((t) => t === 'completed') },
9	  { name: 'ends-only-when-both-reported', pred: (s) => !TERMINAL.includes(s.run) || tasks(s).every(reported) },
10	  { name: 'failed-only-if-a-task-failed', pred: (s) => s.run !== 'failed' || tasks(s).includes('failed') },
11	  { name: 'cancelled-means-none-failed-not-both-completed',
12	    pred: (s) => s.run !== 'cancelled' || (!tasks(s).includes('failed') && !tasks(s).every((t) => t === 'completed')) },
13	  { name: 'both-reported-means-ended', pred: (s) => !tasks(s).every(reported) || TERMINAL.includes(s.run) },
14	  // A busy worker's task is still assigned, or was given up on by a timeout (recorded failed).
15	  { name: 'busy-worker-task-assigned-or-timed-out',
16	    pred: (s) => [0, 1].every((i) => (i === 0 ? s.w0 : s.w1) !== 'busy' || ['assigned', 'failed'].includes(tasks(s)[i])) },
17	  { name: 'task-cancelled-only-after-cancel', pred: (s) => !tasks(s).includes('cancelled') || s.run !== 'running' },
18	  { name: 'idle-run-has-idle-tasks', pred: (s) => s.run !== 'idle' || (s.task0 === 'idle' && s.task1 === 'idle' && s.net.length === 0) },
19	  { name: 'idle-run-not-retried', pred: (s) => s.run !== 'idle' || (!s.retried0 && !s.retried1) },
20	  { name: 'at-most-one-assign-per-task-in-flight', pred: (s) => [0, 1].every((i) => count(s.net, `Assign:${i}`) <= 1) },
21	  { name: 'at-most-one-report-per-task-in-flight',
22	    pred: (s) => [0, 1].every((i) => ['completed', 'failed', 'cancelled'].reduce((n, o) => n + count(s.net, `Report:${i}:${o}`), 0) <= 1) },
23	];
24	
25	export const transitionInvariants = [
26	  { name: 'ended-run-never-changes',
27	    pred: (pre, a, d, post) => !TERMINAL.includes(pre.run) || (post.run === pre.run && post.task0 === pre.task0 && post.task1 === pre.task1) },
28	  { name: 'reported-task-never-changes',
29	    pred: (pre, a, d, post) => [0, 1].every((i) => !reported(tasks(pre)[i]) || tasks(post)[i] === tasks(pre)[i]) },
30	  { name: 'cancel-aborts-only-assigned-work',
31	    pred: (pre, a, d, post) => a !== 'CANCEL' || [0, 1].every((i) =>
32	      count(post.net, `Abort:${i}`) - count(pre.net, `Abort:${i}`) === (pre.run === 'running' && tasks(pre)[i] === 'assigned' ? 1 : 0)) },
33	  { name: 'retried-flag-never-clears',
34	    pred: (pre, a, d, post) => (!pre.retried0 || post.retried0) && (!pre.retried1 || post.retried1) },
35	  { name: 'first-failure-while-running-is-retried',
36	    pred: (pre, a, d, post) => {
37	      if (a !== 'DELIVER' || !/^Report:\d:failed$/.test(d.msg) || !pre.net.includes(d.msg)) return true;
38	      const i = Number(d.msg[7]);
39	      const t = (s) => tasks(s)[i];
40	      const r = (s) => (i === 0 ? s.retried0 : s.retried1);
41	      if (t(pre) !== 'assigned' || TERMINAL.includes(pre.run)) return true;
42	      if (pre.run === 'running' && !r(pre)) {
43	        return t(post) === 'assigned' && r(post) && post.run === pre.run
44	          && count(post.net, `Assign:${i}`) === count(pre.net, `Assign:${i}`) + 1;
45	      }
46	      // second failure, or failure while cancelling: recorded, no retry
47	      return t(post) === 'failed' && r(post) === r(pre) && count(post.net, `Assign:${i}`) === count(pre.net, `Assign:${i}`);
48	    } },
49	  { name: 'only-start-or-retry-sends-assign',
50	    pred: (pre, a, d, post) => a === 'START' || [0, 1].every((i) =>
51	      count(post.net, `Assign:${i}`) <= count(pre.net, `Assign:${i}`)
52	      || (a === 'DELIVER' && d.msg === `Report:${i}:failed` && !(i === 0 ? pre.retried0 : pre.retried1))) },
53	  { name: 'only-cancel-or-timeout-sends-abort',
54	    pred: (pre, a, d, post) => a === 'CANCEL' || [0, 1].every((i) => count(post.net, `Abort:${i}`) <= count(pre.net, `Abort:${i}`)
55	      || (a === 'TIMEOUT' && d.task === i)) },
56	  { name: 'timeout-is-a-final-failure-and-aborts',
57	    pred: (pre, a, d, post) => {
58	      if (a !== 'TIMEOUT') return true;
59	      const i = d.task;
60	      const live = (pre.run === 'running' || pre.run === 'cancelling') && (i === 0 || i === 1) && tasks(pre)[i] === 'assigned';
61	      if (!live) return JSON.stringify(pre) === JSON.stringify(post);
62	      return tasks(post)[i] === 'failed' && count(post.net, `Abort:${i}`) === count(pre.net, `Abort:${i}`) + 1
63	        && (i === 0 ? post.retried0 === pre.retried0 : post.retried1 === pre.retried1)
64	        && count(post.net, `Assign:${i}`) === count(pre.net, `Assign:${i}`);
65	    } },
66	];
67	
68	export default { stateInvariants, transitionInvariants };
